                prev.next = null;
            } else {
                self.first = null;
            }
            self.last = prev;
            self.len -= 1;
            return last_node;
        }

        pub fn shift(self: *@This()) ?*Node {
            const first_node = self.first;
            if (first_node) == null {
                return null;
            }
            const next = first_node.next;
            if (next) {
                next.prev = null;
            } else {
                self.last = null;
            }
            self.first = next;
            self.len -= 1;
            return first_node;
